SELECT 1 FROM runtime_operations op WHERE op.id=?1 AND op.attempt=?2 AND op.status='succeeded' AND op.actor_id=?3 AND CAST(json_extract(op.request,'$.actor_id') AS TEXT)=CAST(?3 AS TEXT) AND CAST(json_extract(op.request,'$.target.bot_id') AS TEXT)=CAST(?4 AS TEXT) AND op.planned_artifact_count=?6 AND op.delivered_artifact_count=?6 AND op.cancel_requested=0 AND ?6 BETWEEN 1 AND 100 AND NOT EXISTS(SELECT 1 FROM runtime_delivery_units du WHERE du.operation_id=op.id AND du.attempt=op.attempt AND du.status<>'sent') AND COALESCE((SELECT SUM(artifact_count) FROM runtime_delivery_units du WHERE du.operation_id=op.id AND du.attempt=op.attempt AND du.status='sent'),0)=?6 AND op.request=?10 AND op.cache_key=?5;